def get_stock_price_by_date(symbol, date, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0343000" if __import__("os").path.isdir("./environment_mix/0343000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        return f"yfs_{prefix}_{uuid.uuid4().hex[:26]}"

    def _parse_iso_any(s):
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)

    def _log(tool_name, symbol_id, fetch_job_id, request_params, response_status, cache_hit, error_message=None):
        logs = _load("api_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "tool_name": tool_name,
            "symbol_id": symbol_id,
            "fetch_job_id": fetch_job_id,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_status": int(response_status),
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "cache_hit": bool(cache_hit),
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("api_request_logs.json", logs)
        return row

    def _rate_limit_ok(tool_name, limit_per_min=120):
        logs = _load("api_request_logs.json")
        if not isinstance(logs, list):
            return True, 0
        one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0)
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tool_name") != tool_name:
                continue
            dt = _parse_iso_any(r.get("created_at"))
            if dt is not None and dt >= one_min_ago:
                recent += 1
        return recent < limit_per_min, recent

    # Validate inputs
    if not isinstance(symbol, str) or not symbol.strip():
        _log("get_stock_price_by_date", None, None, {"symbol": symbol, "date": date}, 422, False, "VALIDATION_ERROR: symbol is required")
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
    symbol_in = symbol.strip()

    if not isinstance(date, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", date.strip()):
        _log("get_stock_price_by_date", None, None, {"symbol": symbol_in, "date": date}, 422, False, "VALIDATION_ERROR: date must be YYYY-MM-DD")
        return _err("VALIDATION_ERROR", "date must be a valid YYYY-MM-DD string")
    date_in = date.strip()
    try:
        datetime.date.fromisoformat(date_in)
    except ValueError:
        _log("get_stock_price_by_date", None, None, {"symbol": symbol_in, "date": date_in}, 422, False, "VALIDATION_ERROR: date is not a real calendar date")
        return _err("VALIDATION_ERROR", "date must be a real calendar date in YYYY-MM-DD format")

    ok, recent = _rate_limit_ok("get_stock_price_by_date", 120)
    if not ok:
        _log("get_stock_price_by_date", None, None, {"symbol": symbol_in, "date": date_in}, 429, False, "Rate limit exceeded: 120 req/min per API key; retry after 10s.")
        return _err("RATE_LIMIT", "Rate limit exceeded: 120 req/min; retry after 10s", retry_after_seconds=10)

    # Upsert symbol
    symbols = _load("symbols.json")
    if not isinstance(symbols, list):
        symbols = []
    sym_row = None
    for r in symbols:
        if isinstance(r, dict) and r.get("symbol") == symbol_in:
            sym_row = r
            break
    if sym_row is None:
        sym_row = {
            "id": _new_id("sym"),
            "symbol": symbol_in,
            "exchange": None,
            "short_name": None,
            "long_name": None,
            "quote_type": "UNKNOWN",
            "currency": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        symbols.append(sym_row)
        _save("symbols.json", symbols)
    else:
        # Keep as-is but touch updated_at
        if sym_row.get("updated_at") != now:
            sym_row["updated_at"] = now
            _save("symbols.json", symbols)

    symbol_id = sym_row.get("id")

    # Try serve cached daily bar
    mdp = _load("market_data_points.json")
    if not isinstance(mdp, list):
        mdp = []

    matches = []
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("symbol_id") != symbol_id:
            continue
        if r.get("data_type") != "price_bar":
            continue
        if r.get("interval") != "1d":
            continue
        if r.get("trading_date") != date_in:
            continue
        matches.append(r)

    def _as_dt_for_sort(row):
        dt = _parse_iso_any(row.get("as_of"))
        if dt is None:
            dt = _parse_iso_any(row.get("updated_at"))
        if dt is None:
            dt = _parse_iso_any(row.get("created_at"))
        return dt or datetime.datetime(1970, 1, 1)

    matches.sort(key=_as_dt_for_sort, reverse=True)
    if matches:
        _log("get_stock_price_by_date", symbol_id, None, {"symbol": symbol_in, "date": date_in}, 200, True, None)
        return {
            "symbol_id": symbol_id,
            "symbol": symbol_in,
            "date": date_in,
            "interval": "1d",
            "data": matches[0],
            "cache_hit": True,
        }

    # Cache miss: enqueue fetch job idempotently, but DO NOT error if missing; return envelope with no data
    jobs = _load("fetch_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    cache_key = f"{symbol_in}|by_date|{date_in}"
    existing_job = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("cache_key") != cache_key:
            continue
        if j.get("status") in ("queued", "running"):
            existing_job = j
            break

    fetch_job_id = None
    if existing_job is None:
        job = {
            "id": _new_id("job"),
            "symbol_id": symbol_id,
            "tool_name": "get_stock_price_by_date",
            "request_params": {"symbol": symbol_in, "date": date_in},
            "cache_key": cache_key,
            "status": "queued",
            "priority": 50,
            "started_at": None,
            "finished_at": None,
            "error_message": None,
            "result_summary": None,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        _save("fetch_jobs.json", jobs)
        fetch_job_id = job["id"]
    else:
        fetch_job_id = existing_job.get("id")

    _log("get_stock_price_by_date", symbol_id, fetch_job_id, {"symbol": symbol_in, "date": date_in}, 200, False, None)
    return {
        "symbol_id": symbol_id,
        "symbol": symbol_in,
        "date": date_in,
        "interval": "1d",
        "data": None,
        "cache_hit": False,
        "fetch_enqueued": True,
        "fetch_job_id": fetch_job_id,
    }

def get_historical_stock_prices(symbol, period=None, interval=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0343000" if __import__("os").path.isdir("./environment_mix/0343000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_ts = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    PERIODS = {"1d", "5d", "1mo", "3mo", "6mo", "1y", "2y", "5y", "10y", "ytd", "max"}
    INTERVALS = {"1d", "5d", "1wk", "1mo", "3mo"}

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(tool_name, symbol_id, fetch_job_id, request_params, response_status, duration_ms, cache_hit, error_message=None):
        logs = _load("api_request_logs.json")
        logs.append({
            "id": _new_id("req"),
            "tool_name": tool_name,
            "symbol_id": symbol_id,
            "fetch_job_id": fetch_job_id,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_status": int(response_status),
            "duration_ms": int(max(0, duration_ms)),
            "cache_hit": bool(cache_hit),
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)

    def _validate_symbol(s):
        if not isinstance(s, str):
            return False, "symbol must be a string"
        if not s.strip():
            return False, "symbol is required"
        if len(s.strip()) < 1 or len(s.strip()) > 20:
            return False, "symbol length must be between 1 and 20"
        return True, None

    def _upsert_symbol(sym):
        symbols = _load("symbols.json")
        sym_norm = sym.strip()
        for r in symbols:
            if isinstance(r, dict) and r.get("symbol") == sym_norm:
                if r.get("status") not in ("active", "inactive", "blocked"):
                    r["status"] = "active"
                r["updated_at"] = now_iso
                _save("symbols.json", symbols)
                return r
        row = {
            "id": _new_id("sym"),
            "symbol": sym_norm,
            "exchange": None,
            "short_name": None,
            "long_name": None,
            "quote_type": "UNKNOWN",
            "currency": None,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        symbols.append(row)
        _save("symbols.json", symbols)
        return row

    def _enqueue_fetch(symbol_row, cache_key, request_params):
        jobs = _load("fetch_jobs.json")
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("cache_key") == cache_key and j.get("status") in ("queued", "running"):
                return j, False
        job = {
            "id": _new_id("job"),
            "symbol_id": symbol_row["id"],
            "tool_name": "get_historical_stock_prices",
            "request_params": request_params,
            "cache_key": cache_key,
            "status": "queued",
            "priority": 50,
            "started_at": None,
            "finished_at": None,
            "error_message": None,
            "result_summary": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        jobs.append(job)
        _save("fetch_jobs.json", jobs)
        return job, True

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None

    def _expected_stale_seconds(intv):
        # heuristic to decide staleness per interval
        return {
            "1d": 24 * 3600,
            "5d": 5 * 24 * 3600,
            "1wk": 7 * 24 * 3600,
            "1mo": 30 * 24 * 3600,
            "3mo": 90 * 24 * 3600,
        }.get(intv, 24 * 3600)

    def _compute_start_date(per):
        today = now.date()
        if per == "1d":
            return today - datetime.timedelta(days=1)
        if per == "5d":
            return today - datetime.timedelta(days=5)
        if per == "1mo":
            return today - datetime.timedelta(days=30)
        if per == "3mo":
            return today - datetime.timedelta(days=90)
        if per == "6mo":
            return today - datetime.timedelta(days=180)
        if per == "1y":
            return today - datetime.timedelta(days=365)
        if per == "2y":
            return today - datetime.timedelta(days=730)
        if per == "5y":
            return today - datetime.timedelta(days=1825)
        if per == "10y":
            return today - datetime.timedelta(days=3650)
        if per == "ytd":
            return datetime.date(today.year, 1, 1)
        if per == "max":
            return None
        return today - datetime.timedelta(days=30)

    ok, msg = _validate_symbol(symbol)
    if not ok:
        dur = int((time.time() - start_ts) * 1000)
        _log("get_historical_stock_prices", None, None, {"symbol": symbol, "period": period, "interval": interval}, 400, dur, False, msg)
        return _err("VALIDATION_ERROR", msg)

    if period is None:
        period = "1mo"
    if interval is None:
        interval = "1d"

    if not isinstance(period, str) or period not in PERIODS:
        dur = int((time.time() - start_ts) * 1000)
        _log("get_historical_stock_prices", None, None, {"symbol": symbol, "period": period, "interval": interval}, 400, dur, False, "invalid period")
        return _err("VALIDATION_ERROR", "period must be one of: " + ", ".join(sorted(PERIODS)))
    if not isinstance(interval, str) or interval not in INTERVALS:
        dur = int((time.time() - start_ts) * 1000)
        _log("get_historical_stock_prices", None, None, {"symbol": symbol, "period": period, "interval": interval}, 400, dur, False, "invalid interval")
        return _err("VALIDATION_ERROR", "interval must be one of: " + ", ".join(sorted(INTERVALS)))

    sym_row = _upsert_symbol(symbol)

    start_d = _compute_start_date(period)
    mdp = _load("market_data_points.json")
    rows = []
    latest_asof = None

    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("symbol_id") != sym_row["id"] or r.get("data_type") != "price_bar":
            continue
        if r.get("interval") != interval:
            continue
        td = r.get("trading_date")
        if start_d is not None:
            if not isinstance(td, str) or not re.match(r"^\d{4}-\d{2}-\d{2}$", td):
                continue
            if td < start_d.isoformat():
                continue
        rows.append(r)
        asof_dt = _parse_dt(r.get("as_of"))
        if asof_dt is not None:
            if latest_asof is None or asof_dt > latest_asof:
                latest_asof = asof_dt

    # Determine staleness: if no data or latest datapoint too old
    stale = False
    if latest_asof is None:
        stale = True
    else:
        age = (now - latest_asof).total_seconds()
        stale = age > _expected_stale_seconds(interval)

    fetch_job = None
    enq = False
    if stale:
        cache_key = f"{sym_row['symbol']}|{period}|{interval}"
        fetch_job, enq = _enqueue_fetch(sym_row, cache_key, {"symbol": sym_row["symbol"], "period": period, "interval": interval})

    # Sort ascending by trading_date then as_of
    rows.sort(key=lambda r: (r.get("trading_date") or "", r.get("as_of") or ""))

    if not rows:
        dur = int((time.time() - start_ts) * 1000)
        _log("get_historical_stock_prices", sym_row["id"], fetch_job.get("id") if fetch_job else None,
             {"symbol": sym_row["symbol"], "period": period, "interval": interval},
             404, dur, False, "No cached historical prices" + ("; fetch enqueued" if fetch_job else ""))
        return _err("NOT_FOUND", "No cached historical prices available (fetch enqueued)" if fetch_job else "No cached historical prices available",
                    fetch_job_id=fetch_job.get("id") if fetch_job else None)

    dur = int((time.time() - start_ts) * 1000)
    _log("get_historical_stock_prices", sym_row["id"], fetch_job.get("id") if fetch_job else None,
         {"symbol": sym_row["symbol"], "period": period, "interval": interval},
         200, dur, not stale, None)
    return {
        "symbol": sym_row["symbol"],
        "symbol_id": sym_row["id"],
        "period": period,
        "interval": interval,
        "data": rows,
        "cache": {"hit": (not stale), "enqueued_fetch": bool(enq), "fetch_job_id": fetch_job.get("id") if fetch_job else None}
    }

def get_dividends(symbol, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0343000" if __import__("os").path.isdir("./environment_mix/0343000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_ts = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(tool_name, symbol_id, fetch_job_id, request_params, response_status, duration_ms, cache_hit, error_message=None):
        logs = _load("api_request_logs.json")
        logs.append({
            "id": _new_id("req"),
            "tool_name": tool_name,
            "symbol_id": symbol_id,
            "fetch_job_id": fetch_job_id,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_status": int(response_status),
            "duration_ms": int(max(0, duration_ms)),
            "cache_hit": bool(cache_hit),
            "error_message": error_message,
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("api_request_logs.json", logs)

    def _validate_symbol(s):
        if not isinstance(s, str):
            return False, "symbol must be a string"
        if not s.strip():
            return False, "symbol is required"
        if len(s.strip()) < 1 or len(s.strip()) > 20:
            return False, "symbol length must be between 1 and 20"
        return True, None

    def _upsert_symbol(sym):
        symbols = _load("symbols.json")
        sym_norm = sym.strip()
        for r in symbols:
            if isinstance(r, dict) and r.get("symbol") == sym_norm:
                if r.get("status") not in ("active", "inactive", "blocked"):
                    r["status"] = "active"
                r["updated_at"] = now_iso
                _save("symbols.json", symbols)
                return r
        row = {
            "id": _new_id("sym"),
            "symbol": sym_norm,
            "exchange": None,
            "short_name": None,
            "long_name": None,
            "quote_type": "UNKNOWN",
            "currency": None,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        symbols.append(row)
        _save("symbols.json", symbols)
        return row

    def _enqueue_fetch(symbol_row, cache_key, request_params):
        jobs = _load("fetch_jobs.json")
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("cache_key") == cache_key and j.get("status") in ("queued", "running"):
                return j, False

        job = {
            "id": _new_id("job"),
            "symbol_id": symbol_row["id"],
            "tool_name": "get_dividends",
            "request_params": request_params,
            "cache_key": cache_key,
            "status": "queued",
            "priority": 50,
            "started_at": None,
            "finished_at": None,
            "error_message": None,
            "result_summary": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        jobs.append(job)
        _save("fetch_jobs.json", jobs)
        return job, True

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    # Quota enforcement (since business rules mention RATE_LIMITED/quota for refresh enqueues)
    # Implement: max 60 dividend fetch enqueues in the past hour across all symbols.
    def _dividend_enqueue_quota_exceeded():
        logs = _load("api_request_logs.json")
        cutoff = now - datetime.timedelta(hours=1)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("tool_name") != "get_dividends":
                continue
            # Count only calls that likely enqueued: cache_hit==False and response_status in (200,404,202) is fine
            if r.get("cache_hit") is True:
                continue
            created = _parse_dt(r.get("created_at"))
            if created is None or created < cutoff:
                continue
            cnt += 1
        return cnt >= 60

    ok, msg = _validate_symbol(symbol)
    if not ok:
        dur = int((time.time() - start_ts) * 1000)
        _log("get_dividends", None, None, {"symbol": symbol}, 400, dur, False, msg)
        return _err("VALIDATION_ERROR", msg)

    sym_row = _upsert_symbol(symbol)

    mdp = _load("market_data_points.json")
    rows = []
    latest_asof = None
    for r in mdp:
        if not isinstance(r, dict):
            continue
        if r.get("symbol_id") != sym_row["id"]:
            continue
        if r.get("data_type") != "dividend":
            continue
        rows.append(r)
        asof_dt = _parse_dt(r.get("as_of"))
        if asof_dt is not None and (latest_asof is None or asof_dt > latest_asof):
            latest_asof = asof_dt

    # Staleness: if no data or last dividend record older than 7 days, refresh
    stale = False
    if latest_asof is None:
        stale = True
    else:
        stale = (now - latest_asof).total_seconds() > 7 * 24 * 3600

    fetch_job = None
    enq = False
    if stale:
        if _dividend_enqueue_quota_exceeded():
            dur = int((time.time() - start_ts) * 1000)
            _log("get_dividends", sym_row["id"], None, {"symbol": sym_row["symbol"]}, 429, dur, False, "Dividend refresh quota exceeded")
            return _err("RATE_LIMIT", "Dividend refresh quota exceeded; try again later")
        cache_key = f"{sym_row['symbol']}|dividends"
        fetch_job, enq = _enqueue_fetch(sym_row, cache_key, {"symbol": sym_row["symbol"]})

    # Order by as_of desc per business rule
    rows.sort(key=lambda r: (r.get("as_of") or ""), reverse=True)

    if not rows:
        dur = int((time.time() - start_ts) * 1000)
        _log("get_dividends", sym_row["id"], fetch_job.get("id") if fetch_job else None,
             {"symbol": sym_row["symbol"]},
             404, dur, False, "No cached dividends" + ("; fetch enqueued" if fetch_job else ""))
        return _err("NOT_FOUND", "No cached dividends available" + (" (fetch enqueued)" if fetch_job else ""),
                    fetch_job_id=fetch_job.get("id") if fetch_job else None)

    dur = int((time.time() - start_ts) * 1000)
    _log("get_dividends", sym_row["id"], fetch_job.get("id") if fetch_job else None,
         {"symbol": sym_row["symbol"]},
         200, dur, not stale, None)
    return {
        "symbol": sym_row["symbol"],
        "symbol_id": sym_row["id"],
        "data": rows,
        "cache": {"hit": (not stale), "enqueued_fetch": bool(enq), "fetch_job_id": fetch_job.get("id") if fetch_job else None}
    }

def get_symbol(id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0343000" if __import__("os").path.isdir("./environment_mix/0343000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            try:
                if v.endswith("Z"):
                    v = v[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        return None

    t0 = time.perf_counter()
    logs = _load("api_request_logs.json")
    symbols = _load("symbols.json")

    # Validate
    if not isinstance(id, str) or not id.strip():
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "tool_name": "cmd_run" if False else "get_symbol",
            "symbol_id": None,
            "fetch_job_id": None,
            "request_params": {"id": id},
            "response_status": 400,
            "duration_ms": max(0, duration_ms),
            "cache_hit": True,
            "error_message": "id must be a non-empty string",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("api_request_logs.json", logs)
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    sym = next((r for r in symbols if r.get("id") == id), None)
    if not sym:
        duration_ms = int((time.perf_counter() - t0) * 1000)
        log_row = {
            "id": "req_" + uuid.uuid4().hex,
            "tool_name": "get_symbol",
            "symbol_id": None,
            "fetch_job_id": None,
            "request_params": {"id": id},
            "response_status": 404,
            "duration_ms": max(0, duration_ms),
            "cache_hit": True,
            "error_message": "Symbol not found",
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        }
        logs.append(log_row)
        _save("api_request_logs.json", logs)
        return _err("NOT_FOUND", "No symbol exists with that id")

    # Success
    duration_ms = int((time.perf_counter() - t0) * 1000)
    log_row = {
        "id": "req_" + uuid.uuid4().hex,
        "tool_name": "get_symbol",
        "symbol_id": sym.get("id"),
        "fetch_job_id": None,
        "request_params": {"id": id},
        "response_status": 200,
        "duration_ms": max(0, duration_ms),
        "cache_hit": True,
        "error_message": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    logs.append(log_row)
    _save("api_request_logs.json", logs)

    return {"symbol": sym}

def update_fetch_job_status(id, status, error_message=None, result_summary=None, started_at=None, finished_at=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0343000" if __import__("os").path.isdir("./environment_mix/0343000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_id(prefix):
        return f"yfs_{prefix}_{uuid.uuid4().hex[:26]}"

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)

    def _fmt(dt_naive_utc):
        return dt_naive_utc.replace(microsecond=0).isoformat() + "Z"

    def _log(tool_name, fetch_job_id, request_params, response_status, cache_hit, error_message=None, symbol_id=None):
        logs = _load("api_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _new_id("req"),
            "tool_name": tool_name,
            "symbol_id": symbol_id,
            "fetch_job_id": fetch_job_id,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "response_status": int(response_status),
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "cache_hit": bool(cache_hit),
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("api_request_logs.json", logs)
        return row

    # Validate inputs
    allowed = {"queued", "running", "succeeded", "failed", "cancelled"}
    if not isinstance(id, str) or not id.strip():
        _log("update_fetch_job_status", None, {"id": id, "status": status}, 422, False, "VALIDATION_ERROR: id is required")
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")
    if not isinstance(status, str) or status not in allowed:
        _log("update_fetch_job_status", None, {"id": id, "status": status}, 422, False, "VALIDATION_ERROR: invalid status")
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled")

    # rate limit: 120 req/min
    logs = _load("api_request_logs.json")
    if not isinstance(logs, list):
        logs = []
    one_min_ago = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0)
    recent = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("tool_name") != "update_fetch_job_status":
            continue
        dt = _parse_rfc3339(r.get("created_at"))
        if dt is not None and dt >= one_min_ago:
            recent += 1
    if recent >= 120:
        _log("update_fetch_job_status", None, {"id": id, "status": status}, 429, False, "Rate limit exceeded: 120 req/min per API key; retry after 10s.")
        return _err("RATE_LIMIT", "Rate limit exceeded: 120 req/min; retry after 10s", retry_after_seconds=10)

    jobs = _load("fetch_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job = None
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == id:
            job = j
            break

    # Tolerant fallback: some callers may pass a symbol id by mistake; update the most relevant queued/running job for that symbol.
    # This matches "accept what is valid under the parameter schema" while still ensuring effect and not silently succeeding.
    if job is None:
        if id.startswith("yfs_sym_"):
            for j in jobs:
                if not isinstance(j, dict):
                    continue
                if j.get("symbol_id") == id and j.get("status") in ("queued", "running", "failed", "cancelled"):
                    job = j
                    break
        if job is None:
            _log("update_fetch_job_status", None, {"id": id, "status": status}, 404, False, f"NOT_FOUND: fetch job not found: {id}")
            return _err("NOT_FOUND", f"fetch job not found: {id}")

    # Lifecycle transitions per schema
    transitions = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": {"queued"},
        "cancelled": {"queued"},
    }
    cur = job.get("status")
    if cur not in transitions:
        _log("update_fetch_job_status", job.get("id"), {"id": job.get("id"), "status": status}, 409, False, f"INVALID_TRANSITION: unknown current status '{cur}'", symbol_id=job.get("symbol_id"))
        return _err("INVALID_TRANSITION", f"Job has invalid current status '{cur}' in datastore")

    if status == cur:
        # idempotent update: still allow updating result/error timestamps if consistent
        pass
    else:
        if status not in transitions[cur]:
            _log("update_fetch_job_status", job.get("id"), {"id": job.get("id"), "from": cur, "to": status}, 409, False, f"INVALID_TRANSITION: {cur} -> {status}", symbol_id=job.get("symbol_id"))
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status} per fetch_jobs lifecycle")

    # Validate and apply timestamps
    started_dt = _parse_rfc3339(started_at) if started_at is not None else None
    finished_dt = _parse_rfc3339(finished_at) if finished_at is not None else None
    if started_at is not None and started_dt is None:
        _log("update_fetch_job_status", job.get("id"), {"id": job.get("id"), "status": status, "started_at": started_at}, 422, False, "VALIDATION_ERROR: started_at must be RFC3339", symbol_id=job.get("symbol_id"))
        return _err("VALIDATION_ERROR", "started_at must be an RFC3339 timestamp (e.g., 2026-08-20T20:00:00Z)")
    if finished_at is not None and finished_dt is None:
        _log("update_fetch_job_status", job.get("id"), {"id": job.get("id"), "status": status, "finished_at": finished_at}, 422, False, "VALIDATION_ERROR: finished_at must be RFC3339", symbol_id=job.get("symbol_id"))
        return _err("VALIDATION_ERROR", "finished_at must be an RFC3339 timestamp (e.g., 2026-08-20T20:00:00Z)")

    # Apply fields
    if status == "running":
        if started_dt is None:
            started_dt = now_dt
        job["started_at"] = _fmt(started_dt)
        job["finished_at"] = None
    elif status in ("succeeded", "failed", "cancelled"):
        if finished_dt is None:
            finished_dt = now_dt
        job["finished_at"] = _fmt(finished_dt)
        # started_at can be set if provided (or left as-is)
        if started_dt is not None:
            job["started_at"] = _fmt(started_dt)
    else:
        # queued: clear finished_at; keep started_at/finished_at semantics (requeue after failed/cancelled)
        job["finished_at"] = None
        if started_dt is not None:
            job["started_at"] = _fmt(started_dt)

    job["status"] = status

    # error_message and result_summary handling
    if error_message is not None:
        if not isinstance(error_message, str):
            _log("update_fetch_job_status", job.get("id"), {"id": job.get("id"), "status": status}, 422, False, "VALIDATION_ERROR: error_message must be string", symbol_id=job.get("symbol_id"))
            return _err("VALIDATION_ERROR", "error_message must be a string when provided")
        job["error_message"] = error_message
    if result_summary is not None:
        # tool schema says string, store expects object or null; accept string and wrap for persistence
        if not isinstance(result_summary, str):
            _log("update_fetch_job_status", job.get("id"), {"id": job.get("id"), "status": status}, 422, False, "VALIDATION_ERROR: result_summary must be string", symbol_id=job.get("symbol_id"))
            return _err("VALIDATION_ERROR", "result_summary must be a string when provided")
        job["result_summary"] = {"summary": result_summary}

    # For succeeded/failed, enforce reasonable message expectations (business-like validation, not too strict)
    if status == "failed" and job.get("error_message") in (None, ""):
        job["error_message"] = "Job marked failed"
    if status == "succeeded" and job.get("result_summary") is None:
        job["result_summary"] = {"summary": "Job succeeded"}

    job["updated_at"] = now

    _save("fetch_jobs.json", jobs)
    _log("update_fetch_job_status", job.get("id"), {"id": job.get("id"), "status": status}, 200, True, None, symbol_id=job.get("symbol_id"))
    return job
